package org.sleepwell.app;

import android.app.*;
import android.content.Intent;
import android.os.*;
import android.widget.*;
import org.json.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;

/** Draft-only alarm override. The parent editor's Save remains the sole persistence action. */
public final class AlarmBedtimeActivity extends Activity {
    static final int REQUEST=685;private Alarm alarm;private AlarmBedtime draft;private String request,error="",preview="";private final ExecutorService reader=Executors.newSingleThreadExecutor();private int generation;private Dialog picker;
    static Intent edit(Activity owner,Alarm alarm,String request){return RecordUi.intent(owner,AlarmBedtimeActivity.class).putExtra("alarm",alarm.json().toString()).putExtra("request",request);}
    @Override public void onCreate(Bundle state){super.onCreate(state);RecordUi.review(this);try{request=getIntent().getStringExtra("request");if(request==null||!UUID.fromString(request).toString().equals(request))throw new IllegalArgumentException();alarm=Alarm.read(new JSONObject(getIntent().getStringExtra("alarm")));if(alarm.nap!=null||alarm.napInvalid)throw new IllegalArgumentException();draft=alarm.bedtime;if(alarm.bedtimeInvalid)error="The saved override needs review. Choose a replacement, then Save alarm.";if(state!=null){draft=AlarmBedtime.decode(new JSONObject(state.getString("draft")));error=state.getString("error","");preview=state.getString("preview","");}if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,this::finish);render();loadPreview();}catch(Exception invalid){finish();}}
    private void render(){LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);RecordUi.header(body,"Alarm bedtime reminder",this::finish);Design.space(body,16);Design.text(body,"For "+alarm.label,21,600,Design.INK);Design.space(body,10);choice(body,"Follow global setting","Use the existing fixed or Smart Bedtime preference.","follow");choice(body,"Off for this alarm","Suppress the reminder when this is the next eligible wake-up.","off");choice(body,"Custom lead before alarm","A fixed elapsed lead before its actual projected occurrence.","custom");if(draft.custom()){Design.space(body,10);PlanActivity.detail(body,"clock","Remind me before wake-up",null,PlanActivity.duration(draft.minutes),this::duration);}Design.space(body,16);Design.text(body,"The earliest eligible wake-up owns tonight’s reminder. Later alarms do not create extra reminders. Dated, sunrise, skipped and calendar-adjusted times are rechecked before delivery.",12,400,Design.MUTED);Design.space(body,12);if(!preview.isEmpty())Design.text(body,preview,14,500,Design.BROWN);Design.space(body,8);Design.text(body,"Custom timing does not subtract the sleep goal, smart window, tracking delay or recorded shortfall again. Existing silent-repeat settings still apply.",12,400,Design.MUTED);PlanActivity.detail(body,"bell","Global bedtime settings","Reminder access, repeats and current delivery status",null,()->startActivity(RecordUi.intent(this,SmartBedtimeActivity.class)));LinearLayout footer=RecordUi.footer(body);if(!error.isEmpty())Design.text(footer,error,13,500,Design.BROWN);Design.text(footer,"Use this draft, then Save alarm. No reminder is scheduled by this screen.",12,400,Design.MUTED);Design.button(footer,"Use reminder setting",true,this::use);Design.button(footer,"Cancel",false,this::finish);}
    private void choice(LinearLayout body,String label,String detail,String mode){Button choice=Design.button(body,label,draft.mode.equals(mode),()->{draft=mode.equals("custom")?new AlarmBedtime(mode,draft.custom()?draft.minutes:540):mode.equals("off")?AlarmBedtime.OFF:AlarmBedtime.FOLLOW;render();loadPreview();});choice.setSelected(draft.mode.equals(mode));Design.text(body,detail,12,400,Design.MUTED);Design.space(body,6);}
    private void duration(){if(picker!=null)picker.dismiss();picker=SleepPicker.duration(this,"Lead before the alarm",draft.minutes,15,1080,value->{draft=new AlarmBedtime("custom",value);render();loadPreview();});}
    private void loadPreview(){int selected=++generation;Alarm snapshot=Alarm.read(alarm.json());AlarmBedtime value=draft;reader.execute(()->{String text;try{long now=System.currentTimeMillis();ZoneId zone=ZoneId.systemDefault();long at=AlarmSkips.next(getApplicationContext(),snapshot,now,zone);text=!snapshot.enabled?"This alarm is off. A reminder requires enabling and saving it.":at<=now?"No eligible future occurrence is available.":value.off()?"No bedtime reminder when this is the next eligible alarm.":value.custom()?"Projected wake-up: "+RecordUi.date(at,zone)+" · "+RecordUi.clock(this,at,zone)+"\nReminder: "+RecordUi.date(at-value.minutes*60000L,zone)+" · "+RecordUi.clock(this,at-value.minutes*60000L,zone)+(at-value.minutes*60000L<=now?" · already passed":""):"Follows the global bedtime preference when this alarm is next.";}catch(RuntimeException unavailable){text="Projection unavailable. The scheduler will require a current eligible occurrence.";}String result=text;runOnUiThread(()->{if(isDestroyed()||isFinishing()||selected!=generation)return;preview=result;render();});});}
    private void use(){try{setResult(RESULT_OK,new Intent().putExtra("request",request).putExtra("bedtime",AlarmBedtime.encode(draft).toString()));finish();}catch(JSONException invalid){error="This reminder setting could not be read.";render();}}
    @Override protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);try{state.putString("draft",AlarmBedtime.encode(draft).toString());}catch(JSONException impossible){throw new IllegalStateException(impossible);}state.putString("error",error);state.putString("preview",preview);}@Override protected void onDestroy(){generation++;if(picker!=null)picker.dismiss();reader.shutdownNow();super.onDestroy();}@Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(focus)RecordUi.lightBars(this);}
}
